  const ex = Number(end.x || 0);
  const ey = Number(end.y || 0);
  let p1, p2, p3, p4;
  if (centerMode) {
    const dx = ex - sx;
    const dy = ey - sy;
    p1 = { x: sx - dx, y: sy - dy };
    p3 = { x: sx + dx, y: sy + dy };
    p2 = { x: p3.x, y: p1.y };
    p4 = { x: p1.x, y: p3.y };
  } else {
    p1 = { x: sx, y: sy };
    p3 = { x: ex, y: ey };
    p2 = { x: p3.x, y: p1.y };
    p4 = { x: p1.x, y: p3.y };
  }
  if (Math.abs(p3.x - p1.x) < SKETCH_MIN_LINE_LENGTH || Math.abs(p3.y - p1.y) < SKETCH_MIN_LINE_LENGTH) {
    return null;
  }
