    if (inputs.debugShowSegments) inputs.debugShowSegments.checked = !!prefs.debugShowSegments;
    if (inputs.debugShowSegmentLabels) inputs.debugShowSegmentLabels.checked = !!prefs.debugShowSegmentLabels;
